#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.66/32 --layer4-configs=all '--description=Block a known bad host'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.66/32 --layer4-configs=all '--description=Block a known bad host'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=2001:db8:66::1/128 --layer4-configs=all '--description=Block a known bad host'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=2001:db8:66::1/128 --layer4-configs=all '--description=Block a known bad host'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.0.2.128/25 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:3389 '--description=Block RDP from the guest half of the admin network'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.0.2.128/25 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:3389 '--description=Block RDP from the guest half of the admin network'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23 '--description=Block telnet out'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23 '--description=Block telnet out'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:23 '--description=Block telnet out'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:23 '--description=Block telnet out'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=198.51.100.10/31,198.51.100.12/30,198.51.100.16/30,198.51.100.20/32,203.0.113.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=Block the scanner networks'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=198.51.100.10/31,198.51.100.12/30,198.51.100.16/30,198.51.100.20/32,203.0.113.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=Block the scanner networks'
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:139,tcp:445 '--description=Block SMB on public networks'
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:139,tcp:445 '--description=Block SMB on public networks'
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:139,tcp:445 '--description=Block SMB on public networks'
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:139,tcp:445 '--description=Block SMB on public networks'
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

